const COMMUNES = MAP.communes.map(c => GEO_NAME[c.nom] || c.nom).sort((a, b) => a.localeCompare(b, "fr"));
const NS = "http://www.w3.org/2000/svg";
const $ = s => document.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const fmt = n => String(n).replace(".", ",");
const keff = e => e.km && e.dp ? Math.round((e.km + e.dp / 100) * 10) / 10 : null;
const dt = d => new Date(d + "T12:00:00");
// a refresh or a new visit starts at the top of the page (the browser no longer puts it back where it was),
