function profileSVG(pts) {
  const { km: d, prof } = trackStats(pts);
  const W = 560, H = 120, l = 38, b = 18, maxE = Math.max(100, Math.ceil(Math.max(...prof.map(p => p[1])) / 100) * 100), maxD = Math.max(1, Math.ceil(d));
  const X = v => l + v / maxD * (W - l - 6), Y = v => 6 + (1 - v / maxE) * (H - b - 6);
  const line = prof.map(p => `${X(p[0]).toFixed(1)},${Y(p[1]).toFixed(1)}`).join(" ");
  const stepE = maxE > 1500 ? 500 : maxE > 600 ? 200 : 100, stepD = maxD > 40 ? 10 : maxD > 16 ? 4 : 2;
  let ticks = "";
  for (let e = 0; e <= maxE; e += stepE) ticks += `<line class="grid" x1="${l}" x2="${W - 6}" y1="${Y(e)}" y2="${Y(e)}"/><text x="${l - 4}" y="${Y(e) + 3}" text-anchor="end">${e}</text>`;
  for (let k = 0; k <= maxD; k += stepD) ticks += `<text x="${X(k)}" y="${H - 4}" text-anchor="middle">${k} km</text>`;
  PROFV = { pts, prof, X, Y, maxD, W, H, l, b };
  return `<svg class="profile" viewBox="0 0 ${W} ${H}" role="img" aria-label="Profil altimétrique sur ${fmt(d)} km. Survolez pour suivre la position sur la carte.">${ticks}
    <polygon class="area" points="${X(0)},${Y(0)} ${line} ${X(prof.at(-1)[0])},${Y(0)}"/><polyline class="ln" points="${line}"/>
    <g class="pf-cur" style="display:none"><line class="pf-v" y1="6" y2="${H - b}"/><circle class="pf-dot" r="4.5"/><g class="pf-lab"><rect rx="4" height="17"/><text y="12"></text></g></g>
    <rect class="pf-hit" x="${l}" y="0" width="${W - l - 6}" height="${H - b}" fill="transparent"/></svg>`;
}

// hovering (or dragging a finger along) the elevation profile moves a marker on the mini map
let PROFV = null;
function profCursor(e) {
  const svgP = e.target.closest && e.target.closest(".profile");
  if (!svgP || !PROFV) return;
  const v = PROFV, ctm = svgP.getScreenCTM(); if (!ctm) return;
  const pt = new DOMPoint(e.clientX, e.clientY).matrixTransform(ctm.inverse());
  const dist = Math.max(0, Math.min(v.prof.at(-1)[0], (pt.x - v.l) / (v.W - v.l - 6) * v.maxD));
  let lo = 0, hi = v.prof.length - 1;
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (v.prof[m][0] < dist) lo = m; else hi = m; }
  const i = Math.abs(v.prof[lo][0] - dist) < Math.abs(v.prof[hi][0] - dist) ? lo : hi;
  const [dk, el] = v.prof[i], x = v.X(dk), y = v.Y(el);
  const g = svgP.querySelector(".pf-cur"); g.style.display = "";
  g.querySelector(".pf-v").setAttribute("x1", x); g.querySelector(".pf-v").setAttribute("x2", x);
  const dot = g.querySelector(".pf-dot"); dot.setAttribute("cx", x); dot.setAttribute("cy", y);
  const txt = `${fmt(Math.round(dk * 10) / 10)} km · ${Math.round(el)} m`, tw = txt.length * 6.1 + 12;
  const lx = Math.min(Math.max(x - tw / 2, v.l), v.W - 6 - tw), lab = g.querySelector(".pf-lab");
  lab.setAttribute("transform", `translate(${lx},${Math.max(2, y - 26)})`); lab.querySelector("rect").setAttribute("width", tw);
  const t = lab.querySelector("text"); t.setAttribute("x", tw / 2); t.textContent = txt;
  const mm = svgP.closest(".trk")?.querySelector(".mm-cur");
  if (mm) { const [mx, my] = P(v.pts[i][0], v.pts[i][1]); mm.setAttribute("transform", `translate(${mx},${my})`); mm.style.display = ""; }
}
function profHide(e) {
  const svgP = e.target.closest && e.target.closest(".profile"); if (!svgP) return;
  svgP.querySelector(".pf-cur").style.display = "none";
  const mm = svgP.closest(".trk")?.querySelector(".mm-cur"); if (mm) mm.style.display = "none";
}
document.addEventListener("pointermove", profCursor);
document.addEventListener("pointerdown", profCursor);
document.addEventListener("pointerout", e => { if (e.target.classList && e.target.classList.contains("pf-hit")) profHide(e); });

